from collections import defaultdict

def find_broken_bikes(bikes, users):
    bike_status = defaultdict(set)
    for user, bike in users.items():
        if bike not in bike_status:
            bike_status[bike].add(user)

    broken_bikes = []
    for bike, users in bike_status.items():
        if len(users) >= bikes[bike]:
            broken_bikes.append(bike)

    return broken_bikes

