from collections import defaultdict

class DinnerParty:
    def __init__(self):
        self.guests = {}

    def add_guest(self, name, age, nationality):
        self.guests[name] = {'age': age, 'nationality': nationality}

    def guest_count_by_nationality(self):
        nationalities = defaultdict(int)
        for guest in self.guests.values():
            nationalities[guest['nationality']] += 1
        return dict(nationalities)

    def guest_ages(self):
        return [guest['age'] for guest in self.guests.values()]

    def oldest_guest(self):
        ages = self.guest_ages()
        return max(ages), ages.index(max(ages))

    def youngest_guest(self):
        ages = self.guest_ages()
        return min(ages), ages.index(min(ages))

    def average_age(self):
        ages = self.guest_ages()
        return sum(ages) / len(ages)

