from functools import lru_cache

@lru_cache(maxsize=100)
def fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

def fib_sequence(n):
    result = []
    for i in range(n):
        result.append(fibonacci(i))
    return result

