from collections import defaultdict

class DinnerParty:
    def __init__(self):
        self.guests = defaultdict(list)
        self.meal_plan = defaultdict(dict)

    def add_guest(self, name, country, occupation, year_born, year_died):
        self.guests[country].append((name, occupation, year_born, year_died))

    def plan_meal(self, guest_country, meal_type, ingredients):
        self.meal_plan[guest_country][meal_type] = ingredients

    def invite(self, country):
        print(f"Inviting guests from {country}:")
        for guest in self.guests[country]:
            name, occupation, year_born, year_died = guest
            print(f"{occupation} {name} ({year_born}-{year_died})")

    def serve(self, guest_country, meal_type):
        print(f"Serving {meal_type} for guests from {guest_country}")
        if meal_type in self.meal_plan[guest_country]:
            ingredients = ', '.join(self.meal_plan[guest_country][meal_type])
            print(f"The ingredients are: {ingredients}")

    def start_party(self):
        for country in self.guests:
            self.invite(country)
            for meal_type in self.meal_plan[country]:
                self.serve(country, meal_type)
            print()

