from jina import Document, Executor, requests

class TextNormalizer(Executor):
    @requests
    def normalize(self, docs: List[Document], **kwargs):
        for doc in docs:
            doc.text = doc.text.lower()
            doc.text = re.sub(r'[^\w\s]', '', doc.text)
            doc.text = ' '.join(doc.text.split())

def normalization_flow():
    with Flow().add(uses=TextNormalizer) as f:
        f.index_files('data/train.csv', recursive=True)

