from collections import defaultdict

def quick_buck(transactions):
    transactions = sorted(transactions, key=lambda x: (x['date'], x['amount']))

    balance = 0
    max_balance = 0
    max_period = []

    for transaction in transactions:
        date = transaction['date']
        amount = transaction['amount']

        balance += amount

        if balance > max_balance:
            max_balance = balance
            max_period = [date]

        elif balance == max_balance:
            max_period.append(date)

    return {'max_balance': max_balance, 'period': max_period}

