figures = ["Albert Einstein", "Ada Lovelace", "Marie Curie", "Nikola Tesla", "Isaac Newton"]

def select_random_guests(figures, num_guests):
    guests = []
    while len(guests) < num_guests:
        guest = figures[randint(0, len(figures)-1)]
        if guest not in guests:
            guests.append(guest)
    return guests

guests = select_random_guests(figures, 5)

print("You have selected the following guests for your special dinner party: ")
for guest in guests:
    print(guest)

from random import randint

def generate_lottery_numbers():
    numbers = set()
    while len(numbers) < 6:
        numbers.add(randint(1, 49))
    return list(numbers)

def check_luck(numbers):
    winning_numbers = [7, 23, 35, 40, 48, 49]
    matches = sum([1 for num in numbers if num in winning_numbers])
    return matches

def play_lottery():
    lottery_numbers = generate_lottery_numbers()
    print(f'Your lottery numbers: {lottery_numbers}')
    matches = check_luck(lottery_numbers)
    if matches == 6:
        print('You won the jackpot!')
    elif matches >= 3:
        print(f'You won a prize! You matched {matches} numbers.')
    else:
        print(f'No match. Better luck next time!')

play_lottery()

