from collections import defaultdict

class DinnerParty:
    def __init__(self):
        self.guests = []
        self.topics = defaultdict(list)

    def add_guest(self, guest):
        self.guests.append(guest)

    def assign_topics(self):
        guests_by_topic = defaultdict(list)
        for guest in self.guests:
            for topic in guest.topics():
                guests_by_topic[topic].append(guest)

        for topic, guests in guests_by_topic.items():
            if len(guests) > 1:
                print(f"\n{topic}")
                for i, guest in enumerate(guests):
                    print(f"{i+1}. {guest.name}")
                    self.topics[topic].append(guest)

    def discuss(self):
        for topic, guests in self.topics.items():
            if len(guests) == 2:
                guest1, guest2 = guests
                print(f"\nDiscussing {topic} with {guest1.name} and {guest2.name}...")

                guest1.talk(topic)
                guest2.talk(topic)
            elif len(guests) == 1:
                guest = guests[0]
                print(f"\nDiscussing {topic} with {guest.name}...")

                guest.talk(topic)
            else:
                print(f"Skipping {topic} because there aren't enough guests.")

class Guest:
    def __init__(self, name, topics):
        self.name = name
        self.topics = topics

    def topics(self):
        return self.topics

    def talk(self, topic):
        pass

class Politician(Guest):
    def talk(self, topic):
        print(f"Politician: 'On the issue of {topic}, I would like to say...'")

class Historian(Guest):
    def talk(self, topic):
        print(f"Historian: 'The historical context of {topic} is... '")

class Scientist(Guest):
    def talk(self, topic):
        print(f"Scientist: 'From a scientific perspective, {topic}...'")

class Philosopher(Guest):
    def talk(self, topic):
        print(f"Philosopher: 'In the realm of philosophy, {topic}...'")

party = DinnerParty()
party.add_guest(Politician("Abraham Lincoln", ["Slavery", "Civil War"]))
party.add_guest(Historian("Napoleon Bonaparte", ["Revolutionary Wars", "Consulate"]))
party.add_guest(Scientist("Albert Einstein", ["Relativity", "Nuclear Physics"]))
party.add_guest(Philosopher("Socrates", ["Ethics", "Education"]))

party.assign_topics()
party.discuss()

from random import randint

def choose_random_figures():
    figures = ['Albert Einstein', 'Nelson Mandela', 'Galileo Galilei', 'Leonardo da Vinci', 'Thomas Edison', 'Marie Curie', 'Winston Churchill']
    return [figures[randint(0, len(figures) - 1)] for _ in range(4)]

def arrange_party(figures):
    print("Welcome to my special dinner party!")
    print("I have invited the following guests:")
    for figure in figures:
        print("- " + figure)

def interact_with_guests(figures):
    for figure in figures:
        if figure == 'Albert Einstein':
            print("Albert: I was once told that I would never make it as a physicist because I was too bad at math. But I believe that curiosity and a willingness to ask questions is more important than having innate talent.")
        elif figure == 'Nelson Mandela':
            print("Nelson: In the face of injustice, we must always speak out and stand up for what is right. But we must also be willing to forgive and work towards reconciliation.")
        elif figure == 'Galileo Galilei':
            print("Galileo: The universe is written in the language of mathematics, and the true way to understand it is through observation and experimentation.")
        elif figure == 'Leonardo da Vinci':
            print("Leonardo: It's not enough to paint or sculpt; one must also understand the underlying principles of art and science to truly create something beautiful.")
        elif figure == 'Thomas Edison':
            print("Edison: Genius is one percent inspiration and ninety-nine percent perspiration. And don't let anyone tell you that failure is not an option; it is always an option, and often necessary for progress.")
        elif figure == 'Marie Curie':
            print("Marie: Science is made by scientists, not by committees. It requires imagination, creativity, and a willingness to question accepted ideas.")
        elif figure == 'Winston Churchill':
            print("Churchill: Never, never, never give up. No matter how many times you fall, you must keep standing up and fighting until you succeed.")

def end_party():
    print("Thank you all for coming to this special dinner party! It was a wonderful conversation and I hope we can do it again soon.")

if __name__ == "__main__":
    figures = choose_random_figures()
    arrange_party(figures)
    interact_with_guests(figures)
    end_party()
